class Solution:
    def minLengthAfterRemovals(self, nums: List[int]) -> int:
        n = len(nums)
        i, j, pairs = 0, (n + 1) // 2, 0
        while i < (n + 1) // 2 and j < n:
            if nums[i] < nums[j]:
                pairs += 1
                i += 1
            j += 1
        return n - 2 * pairs

