class Solution {
public:
    int minLengthAfterRemovals(vector<int>& nums) {
        int n = nums.size();
        int half = (n + 1) / 2;
        int i = 0, j = half, pairs = 0;
        while (i < half && j < n) {
            if (nums[i] < nums[j]) { pairs++; i++; }
            j++;
        }
        return n - 2 * pairs;
    }
};

