class Solution {
public:
    int minLengthAfterRemovals(vector<int>& nums) {
        unordered_map<int, int> cnt;
        int f = 0;
        for (int x : nums) f = max(f, ++cnt[x]);
        return max(2 * f - (int)nums.size(), (int)nums.size() % 2);
    }
};

