class Solution {
    public int minLengthAfterRemovals(int[] nums) {
        Map<Integer, Integer> cnt = new HashMap<>();
        int f = 0;
        for (int x : nums) f = Math.max(f, cnt.merge(x, 1, Integer::sum));
        return Math.max(2 * f - nums.length, nums.length % 2);
    }
}

